"""Readable views of the fixed PM dictionary and completed contract application.
This renderer does not run a model, audit old scores, or repeat the application.
"""
from pathlib import Path
import csv,json
S=Path(__file__).resolve().parents[1];R=S.parents[1];O=R/'research/results/EXP-PM-DEFS-001'
def render():
 c=json.loads((S/'catalog.v1.json').read_text());r=json.loads((O/'contract-run-v2/coverage-and-contracts.json').read_text());sources=json.loads((S/'evidence/rule-sources.json').read_text())
 lines=['# PM component dictionary 1.0.0','', 'Executable schema: `ledger.schema.v1.json`; canonical catalog: `catalog.v1.json`. This is a research data contract, not a production scorer or release.','', '| Definition | Unit / role | Required target distinction | Identity / limit |','| --- | --- | --- | --- |']
 for x in c['components']:lines.append('| '+x['id']+' | '+x['unit']+' / '+x['kind']+' | '+x['target'].replace('|','/')+' | '+x['identity'].replace('|','/')+'; '+x['limits'].replace('|','/')+' |')
 lines+=['','## Canonical point partition','', '`'+ ' + '.join(c['canonical_additive_partition']) +'`','', 'Legacy forecast `expected_bonus` maps to `bonus_points` once. Counts, BPS and diagnostic partitions are not extra FPL point terms. Missing components are not silently zero. Actual official complete/final explain lists have a separate explicit closed-world adapter; provider missing events do not.','', '## Rulebooks and sources','']
 for season,rule in c['rulebooks'].items():lines.append('- '+season+': `'+rule['id']+'`. '+rule.get('limits',rule.get('operational_status','')))
 for source in sources:lines.append('- ['+source['id']+']('+source['url']+'): '+source['status']+'; observed '+source['observed_on']+'.')
 (S/'CATALOG.md').write_text('\n'.join(lines)+'\n')
 rows=[dict(dataset='GW8–10official',target=k,rows=v['rows'],known=v['non_null'],status='direct source field, not a forecast score')for k,v in r['official_field_coverage'].items()]
 for target in ['saves_inside_box','big_chance_saves','nonpenalty_goal_origin','sub_off_second','red_card_time']:
  rows.append(dict(dataset='GW8–10official live stats',target=target,rows=sum(x['official_player_rows']for x in r['by_gw']),known=0,status='no explicit field in inspected stats container; no claim about every external source'))
 for k,v in r['forecast_component_coverage'].items():rows.append(dict(dataset='GW8–10fixture component means',target=k,rows=2007,known=v,status='point expectation, not full event law'))
 with(O/'field-coverage.csv').open('w')as h:
  w=csv.DictWriter(h,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
 lines=['# Data availability and non-identifiability','', 'New field-presence/contract application to old sources; not a new CS/DC/save/BPS accuracy study.','', '| Population / target | Available | Missing / not identified |','| --- | --- | --- |', '| Current original forecast cohort | 2,007 matched players across GW8–10; ten component means and aligned total-points/minutes draws | Per-draw background BPS, event/covariance and ordinary-save subtype law |','| Current official outcomes | 2,011 rows; direct goal/assist/CS/DC/save/BPS/bonus source fields | Four official-only rows have no forecast; no backfill or new score |','| Historical PR32 | Existing 341 fixtures / 27,092 forecast-label rows; p_bps, p_bonus and bg_rate/bg_sd columns | Direct player CS absent (rule-derived); 2024 DC action/award labels unavailable; 2025 scoring rows have penalty-origin ambiguity |','| Raw provider availability, inherited PR41 receipt | 141 inside-save rows; 133 strict; xGOT135, reconciled133 | Big-chance-save flags0; official subtype mapping/use rights not established; raw event payload not shipped here |','| PR42 team-CS bounds, inherited receipt | 57/60 team rows; 1,308 supported eligible player rows | Three team rows and462eligible player rows unsupported; bounds are not confidence intervals |','', 'All new compatibility checks passed for 2,007 forecast and 2,007 matched actual ledgers. Goal-origin and penalty-miss diagnostic identities were applicable in all2,007archived forecast rows. The rule-year-specific official machine point weights are checked in the harness/tests. See `field-coverage.csv` for container-level counts, not independent sample sizes.','', '## Distinguish data from inference','', '- FPL live saves is an observed count. Forecast save-point means do not identify its count distribution.', '- Some targets ARE identified: outfield fixture P(DCaward)=E[DCpoints]/2, qualified-player P(CS)=E[CSpoints]/position_award for nonzero positional awards, and goal/assist count means from their linear point multipliers. This does not identify teamCS, full count laws, or joint BPS dependence.','- Current FPL clean-sheet fields are direct outcome labels; historical PR32 clean sheets were rule-derived and must keep that label.','- PR32 contains historical marginal p_bps/bg_rate/bg_sd; current public player scenarios do not contain the corresponding full event/background trace. Do not generalize either cohort to the other.','- Missing historical penalty-goal or ordinary big-chance-save labels remain unknown. No xGOTthreshold or current webpage is substituted as a historical feature.','- Current official articles are rule evidence observed today, not proof of their original historic delivery time. All old before-deadline forecast issues stay unchanged.','- Source comparisons and known identities are deterministic contract checks; no gain, confidence interval or independent validation is claimed.','']
 (O/'COVERAGE.md').write_text('\n'.join(lines))
if __name__=='__main__':render()
